#include "storage_engine.h"
#include "checksum.h"
#include "errors.h"
#include <fcntl.h>
#include <unistd.h>
#include <algorithm>
#include <chrono>
#include <fstream>
#include <future>
#include <unordered_map>
#include <unordered_set>
namespace flashforge { namespace {
std::size_t workerCount(std::size_t n){return n?n:std::max(1u,std::thread::hardware_concurrency());}
void syncDir(const std::filesystem::path&p){int fd=::open(p.c_str(),O_RDONLY);if(fd>=0){::fsync(fd);::close(fd);}}
std::vector<std::uint8_t> readAll(const std::filesystem::path&p){std::ifstream in(p,std::ios::binary);if(!in)throw StorageException("cannot read chunk: "+p.string());return {(std::istreambuf_iterator<char>(in)),{}};}
}
StorageEngine::StorageEngine(std::filesystem::path root,std::size_t chunk_size,std::size_t workers)
 :root_(std::move(root)),chunks_root_(root_/"chunks"),chunker_(chunk_size),metadata_(root_),wal_(root_/"wal.log"),pool_(workerCount(workers)){
 std::filesystem::create_directories(chunks_root_);metadata_.load();if(auto recovered=wal_.latestCommittedSnapshot()){metadata_.deserialize(*recovered);metadata_.persistAtomic(*recovered);wal_.checkpoint();}rebuildIndex();
}
std::filesystem::path StorageEngine::chunkPath(const std::string&h)const{return chunks_root_/h.substr(0,2)/h.substr(2,2)/h;}
std::vector<Chunk> StorageEngine::prepareChunks(const std::filesystem::path&p){auto chunks=chunker_.chunkFile(p);std::vector<std::future<std::string>>fs;fs.reserve(chunks.size());for(const auto&c:chunks)fs.push_back(pool_.submit([bytes=c.bytes]{return sha256(bytes);}));for(std::size_t i=0;i<chunks.size();++i)chunks[i].hash=fs[i].get();return chunks;}
void StorageEngine::persistChunk(const Chunk&c){auto path=chunkPath(c.hash);if(std::filesystem::exists(path)){auto existing=readAll(path);if(existing!=c.bytes)throw StorageException("SHA-256 collision detected for "+c.hash);return;}std::filesystem::create_directories(path.parent_path());auto tmp=path;tmp+=".tmp."+std::to_string(::getpid())+"."+std::to_string(c.index);int fd=::open(tmp.c_str(),O_WRONLY|O_CREAT|O_EXCL,0644);if(fd<0){if(std::filesystem::exists(path)){auto existing=readAll(path);if(existing!=c.bytes)throw StorageException("SHA-256 collision detected");return;}throw StorageException("cannot create chunk temporary file");}std::size_t d=0;while(d<c.bytes.size()){auto n=::write(fd,c.bytes.data()+d,c.bytes.size()-d);if(n<0){::close(fd);std::filesystem::remove(tmp);throw StorageException("chunk write failed");}d+=static_cast<std::size_t>(n);}if(::fsync(fd)!=0){::close(fd);std::filesystem::remove(tmp);throw StorageException("chunk fsync failed");}::close(fd);std::error_code ec;std::filesystem::rename(tmp,path,ec);if(ec){std::filesystem::remove(tmp);if(!std::filesystem::exists(path))throw StorageException("chunk rename failed: "+ec.message());}syncDir(path.parent_path());}
void StorageEngine::commitState(){auto snapshot=metadata_.serialize();auto tx=wal_.begin(snapshot);wal_.commit(tx);metadata_.persistAtomic(snapshot);wal_.checkpoint();}
void StorageEngine::rebuildIndex(){index_.clear();for(const auto&[id,f]:metadata_.files()){(void)id;for(const auto&h:f.chunk_hashes){auto p=chunkPath(h);if(!std::filesystem::exists(p))throw MetadataException("metadata references missing chunk: "+h);auto size=std::filesystem::file_size(p);if(auto*r=index_.find(h))++r->reference_count;else index_.set(h,{p,size,1});}}}
std::string StorageEngine::put(const std::filesystem::path&source){auto chunks=prepareChunks(source);std::unique_lock lock(state_mutex_);for(const auto&c:chunks)persistChunk(c);FileMetadata f;f.file_id=metadata_.allocateId();f.original_filename=source.filename().string();f.logical_size=std::filesystem::file_size(source);f.creation_timestamp=static_cast<std::uint64_t>(std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()));for(const auto&c:chunks){f.chunk_hashes.push_back(c.hash);if(index_.contains(c.hash))index_.increment(c.hash);else index_.set(c.hash,{chunkPath(c.hash),c.size,1});}auto id=f.file_id;metadata_.upsert(std::move(f));commitState();return id;}
void StorageEngine::get(const std::string&id,const std::filesystem::path&dest)const{std::shared_lock lock(state_mutex_);auto*f=metadata_.find(id);if(!f)throw FileNotFoundException("unknown file id: "+id);auto tmp=dest;tmp+=".tmp."+std::to_string(::getpid());std::ofstream out(tmp,std::ios::binary|std::ios::trunc);if(!out)throw StorageException("cannot create destination: "+dest.string());try{for(const auto&h:f->chunk_hashes){auto bytes=readAll(chunkPath(h));if(sha256(bytes)!=h)throw ChunkCorruptionException("chunk checksum mismatch: "+h);out.write(reinterpret_cast<const char*>(bytes.data()),static_cast<std::streamsize>(bytes.size()));if(!out)throw StorageException("destination write failed");}out.flush();out.close();std::error_code ec;std::filesystem::rename(tmp,dest,ec);if(ec)throw StorageException("destination rename failed: "+ec.message());}catch(...){out.close();std::filesystem::remove(tmp);throw;}}
void StorageEngine::deleteFile(const std::string&id){std::unique_lock lock(state_mutex_);auto*f=metadata_.find(id);if(!f)throw FileNotFoundException("unknown file id: "+id);for(const auto&h:f->chunk_hashes)index_.decrement(h);metadata_.erase(id);commitState();}
void StorageEngine::update(const std::string&id,const std::filesystem::path&source){auto chunks=prepareChunks(source);std::unique_lock lock(state_mutex_);auto*old=metadata_.find(id);if(!old)throw FileNotFoundException("unknown file id: "+id);for(const auto&c:chunks)persistChunk(c);auto created=old->creation_timestamp,version=old->version+1;for(const auto&h:old->chunk_hashes)index_.decrement(h);FileMetadata f{id,source.filename().string(),std::filesystem::file_size(source),created,version,{}};for(const auto&c:chunks){f.chunk_hashes.push_back(c.hash);if(index_.contains(c.hash))index_.increment(c.hash);else index_.set(c.hash,{chunkPath(c.hash),c.size,1});}metadata_.upsert(std::move(f));commitState();}
std::vector<FileMetadata> StorageEngine::listFiles()const{std::shared_lock lock(state_mutex_);std::vector<FileMetadata>v;for(const auto&[id,f]:metadata_.files()){(void)id;v.push_back(f);}std::sort(v.begin(),v.end(),[](const auto&a,const auto&b){return a.file_id<b.file_id;});return v;}
StorageStats StorageEngine::stats()const{std::shared_lock lock(state_mutex_);StorageStats s;s.file_count=metadata_.files().size();for(const auto&[id,f]:metadata_.files()){(void)id;s.logical_size+=f.logical_size;s.total_chunk_references+=f.chunk_hashes.size();}for(const auto&[h,r]:index_.entries()){(void)h;if(r.reference_count){s.physical_size+=r.size;++s.unique_chunks;}}s.space_saved=s.logical_size>s.physical_size?s.logical_size-s.physical_size:0;s.dedup_ratio=s.physical_size?static_cast<double>(s.logical_size)/s.physical_size:(s.logical_size?0.0:1.0);return s;}
GCStats StorageEngine::collectGarbage(){std::unique_lock lock(state_mutex_);GCStats s;std::unordered_set<std::string>live;for(const auto&[h,r]:index_.entries())if(r.reference_count)live.insert(h);if(!std::filesystem::exists(chunks_root_))return s;for(const auto&e:std::filesystem::recursive_directory_iterator(chunks_root_)){if(!e.is_regular_file())continue;auto name=e.path().filename().string();if(name.find(".tmp.")!=std::string::npos)continue;++s.chunks_scanned;if(!live.count(name)){auto bytes=e.file_size();std::error_code ec;std::filesystem::remove(e.path(),ec);if(!ec){++s.chunks_deleted;s.bytes_reclaimed+=bytes;index_.erase(name);}}}return s;}
std::uint64_t StorageEngine::chunkRefCount(const std::string&h)const{std::shared_lock lock(state_mutex_);auto*r=index_.find(h);return r?r->reference_count:0;}
}

